import { describe, expect, it } from 'vitest';
import { exposureShare } from './Solution';

/**
 * 断言由 gen.py 里的同一个 share() 模型生成，不手抄 ——
 * react-vitest 题的判分事实来源就是这份测试文件，抄错一次就永久错一次。
 */
describe('exposureShare：曝光份额与供给份额', () => {
  it("基线：新供给只拿到 1.2% 曝光，判为投放不足", () => {
    expect(exposureShare([{"segment": "new", "supply": 60, "impressions": 120}, {"segment": "established", "supply": 940, "impressions": 9880}])).toEqual([{"segment": "new", "supplySharePct": 6.0, "exposureSharePct": 1.2, "gapPct": -4.8, "underExposed": true, "untracked": false}, {"segment": "established", "supplySharePct": 94.0, "exposureSharePct": 98.8, "gapPct": 4.8, "underExposed": false, "untracked": false}]);
  });
  it("份额分母是总量而不是行平均：两行的段权重要按供给算", () => {
    expect(exposureShare([{"segment": "a", "supply": 100, "impressions": 40}, {"segment": "b", "supply": 100, "impressions": 960}])).toEqual([{"segment": "a", "supplySharePct": 50.0, "exposureSharePct": 4.0, "gapPct": -46.0, "underExposed": true, "untracked": false}, {"segment": "b", "supplySharePct": 50.0, "exposureSharePct": 96.0, "gapPct": 46.0, "underExposed": false, "untracked": false}]);
  });
  it("未采集的那一段：供给与曝光两侧都剔除", () => {
    expect(exposureShare([{"segment": "a", "supply": 400, "impressions": 500}, {"segment": "b", "supply": 400, "impressions": 500}, {"segment": "broken", "supply": 200, "impressions": null}])).toEqual([{"segment": "a", "supplySharePct": 50.0, "exposureSharePct": 50.0, "gapPct": 0.0, "underExposed": false, "untracked": false}, {"segment": "b", "supplySharePct": 50.0, "exposureSharePct": 50.0, "gapPct": 0.0, "underExposed": false, "untracked": false}, {"segment": "broken", "supplySharePct": null, "exposureSharePct": null, "gapPct": null, "underExposed": false, "untracked": true}]);
  });
  it("阈值是严格小于：正好 0.8 倍不算投放不足", () => {
    expect(exposureShare([{"segment": "x", "supply": 100, "impressions": 400}, {"segment": "y", "supply": 100, "impressions": 600}])).toEqual([{"segment": "x", "supplySharePct": 50.0, "exposureSharePct": 40.0, "gapPct": -10.0, "underExposed": false, "untracked": false}, {"segment": "y", "supplySharePct": 50.0, "exposureSharePct": 60.0, "gapPct": 10.0, "underExposed": false, "untracked": false}]);
  });
  it("零曝光的一段：份额 0 且必然判为不足", () => {
    expect(exposureShare([{"segment": "z", "supply": 50, "impressions": 0}, {"segment": "w", "supply": 50, "impressions": 900}])).toEqual([{"segment": "z", "supplySharePct": 50.0, "exposureSharePct": 0.0, "gapPct": -50.0, "underExposed": true, "untracked": false}, {"segment": "w", "supplySharePct": 50.0, "exposureSharePct": 100.0, "gapPct": 50.0, "underExposed": false, "untracked": false}]);
  });
  it("退化：完全没有曝光数据 ⇒ 两侧分母都是 0，份额全记 0", () => {
    expect(exposureShare([{"segment": "a", "supply": 0, "impressions": 0}])).toEqual([{"segment": "a", "supplySharePct": 0.0, "exposureSharePct": 0.0, "gapPct": 0.0, "underExposed": false, "untracked": false}]);
  });
  it("退化：没有任何分段", () => {
    expect(exposureShare([])).toEqual([]);
  });
  it("非法：分段名重复", () => {
    expect(() => exposureShare([{"segment": "a", "supply": 1, "impressions": 1}, {"segment": "a", "supply": 2, "impressions": 2}] as never)).toThrow("duplicated segment");
  });
  it("非法：供给为负", () => {
    expect(() => exposureShare([{"segment": "a", "supply": -1, "impressions": 1}] as never)).toThrow("negative supply");
  });
  it("非法：曝光为负", () => {
    expect(() => exposureShare([{"segment": "a", "supply": 1, "impressions": -5}] as never)).toThrow("negative impressions");
  });
  it("非法：分段名是空串", () => {
    expect(() => exposureShare([{"segment": "", "supply": 1, "impressions": 1}] as never)).toThrow("empty segment");
  });
});

